insert into public.recipes (slug, title_es, title_en, summary_es, summary_en, minutes, servings, meal_types, vegetarian, steps_es, steps_en, image_key) values ('pasta-integral-con-tomate-y-atun', 'Pasta integral con tomate y atún', 'Wholemeal pasta with tomato and tuna', 'El clásico de despensa, con pasta integral para sumar fibra.', 'The pantry classic, with wholemeal pasta for extra fibre.', 15, 2, array['lunch']::text[], false, array['Cuece la pasta según el envase y escúrrela.', 'Calienta la salsa con el aceite y añade el atún escurrido.', 'Mezcla con la pasta y sirve.']::text[], array['Cook the pasta as directed on the pack and drain.', 'Warm the sauce with the oil and add the drained tuna.', 'Toss with the pasta and serve.']::text[], 'pasta-cocida') on conflict (slug) do update set title_es = excluded.title_es, title_en = excluded.title_en, summary_es = excluded.summary_es, summary_en = excluded.summary_en, minutes = excluded.minutes, servings = excluded.servings, meal_types = excluded.meal_types, vegetarian = excluded.vegetarian, steps_es = excluded.steps_es, steps_en = excluded.steps_en, image_key = excluded.image_key;
